NAME = 'SrKDIjekav: Serbian Bible Daničić-Karadžić Ijekavski'
BOOK = 'Zephaniah'

CHAPTERS = {
    1: {
        1: 'Ријеч Господња која дође Софонији сину Хусија сина Годолије сина Амарије сина Језекијина, за времена Јосије сина Амонова, цара Јудина.',
        2: 'Све ћу узети са земље, говори Господ;',
        3: 'Узећу људе и стоку, узећу птице небеске и рибе морске и саблазни с безбожницима, и истријебићу људе са земље, говори Господ.',
        4: 'Јер ћу махнути руком својом на Јуду и на све становнике Јерусалимске, и истријебићу из мјеста овога остатак Валов и име свештеника идолских с другим свештеницима,',
        5: 'И оне који се клањају на крововима војсци небеској и који се клањају и куну се Господом и који се куну Мелхомом.',
        6: 'И оне који се одвраћају од Господа и који не траже Господа нити питају за њ.',
        7: 'Мучи пред Господом Господом, јер је близу дан Господњи, јер је Господ приготовио жртву и позвао своје званице.',
        8: 'И у дан жртве Господње походићу кнезове и царске синове и све који носе туђинско одијело.',
        9: 'И походићу у тај дан све који скачу преко прага, који пуне кућу господара својих грабежем и пријеваром.',
        10: 'И у тај ће дан, вели Господ, бити вика од рибљих врата, и јаук с друге стране, и полом велик с хумова.',
        11: 'Ридајте који живите у Мактесу, јер изгибе сав народ трговачки, истријебише се сви који носе сребро.',
        12: 'И у то ћу вријеме разгледати Јерусалим са жишцима, и походићу људе који леже на својој дрождини, који говоре у срцу свом: Господ не чини ни добро ни зло.',
        13: 'И благо ће се њихово разграбити и куће њихове опустошити; граде куће, али неће сједјети у њима; и саде винограде, али неће пити вина из њих.',
        14: 'Близу је велики дан Господњи, близу је и иде врло брзо; глас ће бити дана Господњега, горко ће тада викати јунак.',
        15: 'Тај је дан дан, када ће бити гњев, дан, када ће бити туга и мука, дан, када ће бити пустошење и затирање, дан, када ће бити мрак и тама, дан, када ће бити облак и магла,',
        16: 'Дан, када ће бити трубљење и поклич на тврде градове и на високе углове.',
        17: 'И притијеснићу људе, те ће ићи као слијепи, јер згријешише Господу; и крв ће се њихова просути као прах и тјелеса њихова као гној.',
        18: 'Ни сребро њихово ни злато њихово неће их моћи избавити у дан гњева Господњега; и сву ће земљу прождријети огањ ревности његове; јер ће брзо учинити крај свјема становницима земаљским.',
    },
    2: {
        1: 'Саберите се, саберите се, народе немили,',
        2: 'Док није изашао суд, и дан прошао као пљева, док није дошао на вас љути гњев Господњи, док није дошао на вас дан гњева Господњега.',
        3: 'Тражите Господа сви који сте кротки у земљи, који чините што је наредио; тражите правду, тражите кротост, еда бисте се сакрили на дан гњева Господњега.',
        4: 'Јер ће се Газа оставити и Аскалон ће опустјети; Азот ће се одагнати у подне и Акарон ће се искоријенити.',
        5: 'Тешко онима који живе по бреговима морским, народу Херетејском: ријеч је Господња на вас, Ханане, земљо Филистејска, ја ћу те затрти да не буде становника у теби.',
        6: 'И брегови ће морски бити станови и јаме пастирске и торови за стада.',
        7: 'И тај ће крај бити остатку дома Јудина; ондје ће пасти; у домовима ће Аскалонским лијегати увече; јер ће их походити Господ Бог њихов и повратити робље њихово.',
        8: 'Чуо сам руг Моавов и укоре синова Амоновијех којима ружише мој народ, и раширише се преко међа њиховијех.',
        9: 'Зато, тако ја био жив, говори Господ над војскама, Бог Израиљев, Моав ће бити као Содом и синови Амонови као Гомор, мјесто копривама, и сланица и вјечна пустош: остатак народа мојега оплијениће их, и који остану од народа мојега наслиједиће их.',
        10: 'То ће им бити за поноситост њихову; јер ружише народ Господа над војскама и подизаше се на њ.',
        11: 'Страшан ће им бити Господ, јер ће истријебити све богове земаљске, и њему ће се клањати сваки из својега мјеста, сва острва народна.',
        12: 'И ви, Етиопљани, бићете побијени мачем мојим.',
        13: 'И дигнуће руку своју на сјевер, и затрће Асириску, и Ниневију ће опустити да буде суха као пустиња.',
        14: 'И у њој ће лежати стада, свакојако звијерје између народа, и гем и ћук ноћиваће на довратницима њезинијем; гласом ће пјевати на прозорима; пустош ће бити на праговима; јер ће се поскидати кедровина.',
        15: 'Таки ће бити весели град, који сједи без бриге, који говори у срцу свом: ја сам, и осим мене нема другога. Како опустје! поста ложа звијерју! Ко год прође мимо њ звиждаће и махати руком.',
    },
    3: {
        1: 'Тешко граду одметничком и оскврњеном, насилничком!',
        2: 'Не слуша гласа, не прима наука, не узда се у Господа, не приступа к Богу својему.',
        3: 'Кнезови су му у њему лавови који ричу; судије су му вуци вечерњи, који не глођу кости до јутра.',
        4: 'Пророци су му хвалише, варалице; свештеници његови скврне светињу, изврћу закон.',
        5: 'Господ је праведан усред њега, не чини неправде, свако јутро износи суд свој на видјело, не изостаје, али безбожник не зна за стид.',
        6: 'Истријебих народе, куле им се разорише, улице им опустих, те нико не пролази; градови им се раскопаше, да нема никога, нема становника.',
        7: 'Рекох: побојаћеш ме се, примићеш наук; неће му се затрти стан ничим су чим бих га походио; али они уранише те покварише сва дјела своја.',
        8: 'Зато чекајте ме, говори Господ, до дана кад ћу се подигнути на плијен; јер је суд мој да саберем народе и покупим царства, да излијем на њих гњев свој, сву жестину јарости своје, јер ће огањ ревности моје прождријети сву земљу.',
        9: 'Јер ћу тада промијенити народима усне, те ће бити чисте, да би сви призивали име Господње и служили му сложнијем раменима.',
        10: 'Испреко ријека Хуских који се мени моле, расијани моји, донијеће ми даре.',
        11: 'Тада се нећеш више стидјети ниједнога својих дјела, којима си ми згријешио; јер ћу онда узети из тебе оне који се хвале славом твојом, и нећеш се више величати на светој гори мојој.',
        12: 'И оставићу у теби народ невољан и сиромашан, и они ће се уздати у име Господње.',
        13: 'Остатак Израиљев неће чинити безакоња нити ће говорити лажи, нити ће се наћи у устима њиховијем језик пријеваран; него ће пасти и лежати и неће бити никога да их плаши.',
        14: 'Пјевај, кћери Сионска; кликуј, Израиљу; радуј се и весели се из свега срца, кћери Јерусалимска!',
        15: 'Уклони Господ судове твоје, одврати непријатеље твоје; цар Израиљев Господ усред тебе је, нећеш се више бојати зла.',
        16: 'У онај дан рећи ће се граду Јерусалиму: не бој се; Сиону: немој да ти клону руке.',
        17: 'Господ Бог твој, који је усред тебе, силни, спашће те; радоваће ти се веома, умириће се у љубави својој, веселиће се тебе ради пјевајући.',
        18: 'Који туже за празницима, сабраћу их, који су из тебе, ради тешке срамоте која је на теби.',
        19: 'Гле, уништићу у оно вријеме све који те муче, и избавићу хроме и сабрати одагнане, и добавићу им хвалу и славу по свој земљи, гдје су били под срамотом.',
        20: 'У оно вријеме довешћу вас, у оно вријеме сабраћу вас; јер ћу вам добавити славу и хвалу по свијем народима на земљи, кад повратим робље ваше пред вашим очима, говори Господ.',
    },
}
